contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 dummy) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        uint256 beforeCBal = address(c).balance;
        uint256 beforeSelfBal = address(this).balance;
        bool reverted;
        c.sudicideAnyone(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        uint256 afterCBal = address(c).balance;
        uint256 afterSelfBal = address(this).balance;

        assert((reverted && afterCBal == beforeCBal && afterSelfBal == beforeSelfBal)
            || (!reverted && afterCBal == 0 && afterSelfBal >= beforeSelfBal));
    }

    receive() external payable {}
}

