// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleSuicide c;

    function setUp() public {
        c = new SimpleSuicide();
    }

    function _run(uint256 dummy) internal {
        vm.deal(address(c), VALUE_CAP);
        uint256 beforeCBal = address(c).balance;
        uint256 beforeSelfBal = address(this).balance;
        bool reverted;
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterCBal = address(c).balance;
        uint256 afterSelfBal = address(this).balance;
        assertTrue((reverted && afterCBal == beforeCBal && afterSelfBal == beforeSelfBal)
            || (!reverted && afterCBal == 0 && afterSelfBal >= beforeSelfBal));
    }

    function testFuzz_run(uint256 dummy) public {
        _run(dummy);
    }

    receive() external payable {}
}
